# metrics.py
from functools import lru_cache

@lru_cache(maxsize=None)            # 'it is just memoization'
def render_label(endpoint: str, user_id: int, day: str) -> str:
    return f"{endpoint}:{user_id}:{day}"

def record(req):
    label = render_label(req.endpoint, req.user_id, today())
    COUNTERS[label] = COUNTERS.get(label, 0) + 1

COUNTERS: dict[str, int] = {}       # exported to the scraper

