from datetime import datetime

class Event:
    def __init__(self, user_id, kind, country, ts=None, tags=[]):
        self.user_id = user_id
        self.kind = kind          # one of ~8 values
        self.country = country    # ISO code, ~200 values
        self.ts = ts or datetime.utcnow()
        self.tags = tags
        self.raw = str(user_id) + kind + country  # cached label

CACHE: dict[int, Event] = {}

def ingest(ev_dict):
    e = Event(**ev_dict)
    CACHE[ev_dict["user_id"]] = e
